// HARDENED: Full Jitter exponential backoff with retry budget
public Response callService(Request req) {
    if (!retryBudget.acquireToken()) {
        throw new RetryBudgetExhaustedException("Shedding retries under cluster distress");
    }
    // Full Jitter: Uniform random backoff breaks synchronized wave patterns
    long sleepMs = (long) (Math.random() * Math.min(maxBackoffMs, baseMs * Math.pow(2, attempt)));
    scheduledExecutor.schedule(() -> executeCall(req), sleepMs, TimeUnit.MILLISECONDS);
}
